class O{int r,z[]=new int[256];String s(boolean p,String[]I){var m=new java.util.LinkedHashMap();for(var x:I[0].split(","))if(p)r+=h(x);else{var q=x.split("\\W");m.compute(q[0],(K,V)->q.length<2?null:q[1]);}m.forEach((k,v)->r+=-~h(k)*++z[h(k)]*new Integer(v+""));return r+"";}int h(Object s){return(s+"").chars().reduce(0,(v,c)->(v+c)*17%256);}}